	// Create data source
	var dataCh <-chan map[string]interface{}
	var errCh <-chan error
	if flagURL != "" {
		dataCh, errCh = urlDataSource(flagURL, flagInterval)
	} else {
		dataCh, errCh = stdinDataSource()
	}

	// Initialize plot state
	plotState := newPlotState(specs, flagSteps)

	// Terminal setup
	term.Setup(numRows)

	// Render loop
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	needRender := false
	done := false

	for !done {
		select {
		case data, ok := <-dataCh:
			if !ok {
				done = true
				break
			}
			plotState.AddData(data)
			needRender = true
		case err = <-errCh:
			if err != nil && err != io.EOF {
				fmt.Fprintf(os.Stderr, "jplot:  Data source error:  %v\n", err)
			}
			done = true
		case <-ticker.C:
			if needRender {
				img := plotState.Render(imgW, imgH)
				if err := term.DisplayImage(img, imgW, imgH); err != nil {
					done = true
					break
				}
				needRender = false
			}
		}
	}

	// Final render if needed
	if needRender {
		img := plotState.Render(imgW, imgH)
		_ = term.DisplayImage(img, imgW, imgH)
	}

	term.Cleanup(numRows)
}

func usage() {
	fmt.Fprint(os.Stderr, `Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:

OPTIONS:
  -interval duration
    	When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)
  -rows int
    	Limits the height of the graph output.
  -steps int
    	Number of values to plot. (default 100)
  -url string
    	URL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
`)
}

// FieldSpec represents one data series spec
type FieldSpec struct {
	Path    string
	Counter bool
	Marker  bool
}

// GraphSpec groups multiple field specs for one graph
type GraphSpec []FieldSpec

func parseFieldSpecs(args []string) ([]GraphSpec, error) {
	var result []GraphSpec
	for _, arg := range args {
		parts := strings.Split(arg, "+")
		var graphSpec GraphSpec
		for _, part := range parts {
			fs, err := parseOneSeries(part)
			if err != nil {
				return nil, err
			}
			graphSpec = append(graphSpec, fs)
		}
		result = append(result, graphSpec)
	}
	return result, nil
}

func parseOneSeries(s string) (FieldSpec, error) {
	fs := FieldSpec{}
	// Check if there are options: option1,option2:path
	idx := strings.Index(s, ":")
	if idx >= 0 {
		optStr := s[:idx]
		fs.Path = s[idx+1:]
		opts := strings.Split(optStr, ",")
		for _, opt := range opts {
			switch opt {
			case "counter":
				fs.Counter = true
			case "marker":
				fs.Marker = true
			default:
				return fs, fmt.Errorf("unknown option: %s", opt)
			}
		}
	} else {
		fs.Path = s
	}
	return fs, nil
}

// getJSONValue navigates a dot-separated path in a JSON object
func getJSONValue(data map[string]interface{}, path string) (float64, bool) {
	parts := strings.Split(path, ".")
	var current interface{} = data
	for _, part := range parts {
		m, ok := current.(map[string]interface{})
		if !ok {
			return 0, false
		}
		current, ok = m[part]
		if !ok {
			return 0, false
		}
	}
	switch v := current.(type) {
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int64:
		return float64(v), true
	default:
		return 0, false
	}
}

// PlotState manages data buffers and rendering
type PlotState struct {
	specs   []GraphSpec
	steps   int
	buffers [][][]float64 // [graph][series][step]
	prevs   [][]float64   // previous values for counter mode
	counts  []int         // number of data points added
}

func newPlotState(specs []GraphSpec, steps int) *PlotState {
	ps := &PlotState{
		specs: specs,
		steps: steps,
	}
	for _, gs := range specs {
		var graphBuf [][]float64
		var prevRow []float64
		for range gs {
			graphBuf = append(graphBuf, make([]float64, steps))
			prevRow = append(prevRow, math.NaN())
		}
		ps.buffers = append(ps.buffers, graphBuf)
		ps.prevs = append(ps.prevs, prevRow)
		ps.counts = append(ps.counts, 0)
	}
	return ps
}

func (ps *PlotState) AddData(data map[string]interface{}) {
	for gi, gs := range ps.specs {
		count := ps.counts[gi]
		pos := count % ps.steps
		for si, fs := range gs {
			val, ok := getJSONValue(data, fs.Path)
			if !ok {
				val = math.NaN()
			}
			if fs.Counter {
				prev := ps.prevs[gi][si]
				if !math.IsNaN(prev) && !math.IsNaN(val) {
					ps.buffers[gi][si][pos] = val - prev
				} else {
					ps.buffers[gi][si][pos] = math.NaN()
				}
				ps.prevs[gi][si] = val
			} else {
				ps.buffers[gi][si][pos] = val
			}
		}
		ps.counts[gi]++
	}
}

func (ps *PlotState) Render(w, h int) []byte {
	nGraphs := len(ps.specs)
	if nGraphs == 0 {
		return nil
	}
	graphH := h / nGraphs
	totalH := graphH * nGraphs

	img := newImage(w, totalH)
	for gi, gs := range ps.specs {
		y0 := gi * graphH
		y1 := y0 + graphH
		buf := ps.buffers[gi]
		count := ps.counts[gi]
		renderGraph(img, w, y0, y1, gs, buf, count, ps.steps)
	}
	return encodePNG(img)
}

// Data sources
func stdinDataSource() (<-chan map[string]interface{}, <-chan error) {
	dataCh := make(chan map[string]interface{}, 10)
	errCh := make(chan error, 1)
	go func() {
		defer close(dataCh)
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var data map[string]interface{}
			if err := json.Unmarshal(line, &data); err != nil {
				continue // skip malformed lines
			}
			dataCh <- data
		}
		if err := scanner.Err(); err != nil {
			errCh <- err
		} else {
			errCh <- io.EOF
		}
	}()
	return dataCh, errCh
}

func urlDataSource(url string, interval time.Duration) (<-chan map[string]interface{}, <-chan error) {
	dataCh := make(chan map[string]interface{}, 10)
	errCh := make(chan error, 1)
	go func() {
		defer close(dataCh)
		for {
			resp, err := http.Get(url)
			if err != nil {
				errCh <- fmt.Errorf("cannot fetch %s: %v", url, err)
				return
			}
			var data map[string]interface{}
			if err := json.NewDecoder(resp.Body).Decode(&data); err != nil {
				resp.Body.Close()
				errCh <- fmt.Errorf("cannot decode response from %s: %v", url, err)
				return
			}
			resp.Body.Close()
			dataCh <- data
			time.Sleep(interval)
		}
	}()
	return dataCh, errCh
}
