package main

import (
	"bufio"
	"encoding/base64"
	"fmt"
	"os"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

// Terminal interface
type Terminal interface {
	GetSize() (cols, rows int, err error)
	GetPixelSize(cols, rows, rowsFlag int) (w, h int, err error)
	Setup(numRows int)
	DisplayImage(imgData []byte, w, h int) error
	Cleanup(numRows int)
}

// Winsize for ioctl
type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinsize() (Winsize, error) {
	var ws Winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(0x5413), // TIOCGWINSZ
		uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return ws, errno
	}
	return ws, nil
}

// Terminal detection
func detectTerminal() (Terminal, error) {
	// First try to query Kitty support
	kittyTerm := &KittyTerminal{}
	if ok := kittyTerm.querySupport(); ok {
		return kittyTerm, nil
	}

	// Check TERM_PROGRAM for iTerm2 or other supported terminals
	termProg := os.Getenv("TERM_PROGRAM")
	switch termProg {
	case "iTerm.app":
		return &ITerm2Terminal{}, nil
	case "WarpTerminal", "Hyper":
		// These support iTerm2 protocol
		return &ITerm2Terminal{}, nil
	}

	// Try querying terminal via ESC[c (Device Attributes)
	if hasSixel, hasKitty := queryTerminalCapabilities(); hasKitty {
		_ = hasSixel
		kittyTerm2 := &KittyTerminal{}
		kittyTerm2.detected = true
		return kittyTerm2, nil
	} else if hasSixel {
		return &SixelTerminal{}, nil
	}

	return nil, fmt.Errorf("iTerm2, Kitty, or DRCS Sixel graphics required")
}

// queryTerminalCapabilities sends ESC[c and reads response
func queryTerminalCapabilities() (hasSixel, hasKitty bool) {
	// Set stdin to raw mode temporarily
	origState, err := makeRaw()
	if err != nil {
		return false, false
	}
	defer restoreRaw(origState)

	// Send Primary DA request
	fmt.Fprint(os.Stdout, "\x1b[c")

	// Read response with timeout
	ch := make(chan string, 1)
	go func() {
		reader := bufio.NewReader(os.Stdin)
		var response strings.Builder
		// Wait for ESC[?...c response
		for {
			b, err := reader.ReadByte()
			if err != nil {
				break
			}
			response.WriteByte(b)
			if b == 'c' && response.Len() > 1 {
				break
			}
		}
		ch <- response.String()
	}()

	select {
	case resp := <-ch:
		// Parse response ESC[?62;...c
		if strings.Contains(resp, "?") {
			params := resp[strings.Index(resp, "?")+1:]
			params = strings.TrimSuffix(params, "c")
			for _, p := range strings.Split(params, ";") {
				n, _ := strconv.Atoi(p)
				if n == 4 { // Sixel support
					hasSixel = true
				}
			}
		}
	case <-time.After(500 * time.Millisecond):
	}

	return hasSixel, false
}

// iTerm2 Terminal implementation
type ITerm2Terminal struct {
	cellW float64
	cellH float64
	imageDisplayed bool
	out *bufio.Writer
}

func (t *ITerm2Terminal) GetSize() (cols, rows int, err error) {
	ws, err := getWinsize()
	if err != nil {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Col), int(ws.Row), nil
}

func (t *ITerm2Terminal) GetPixelSize(cols, rows, rowsFlag int) (int, int, error) {
	// Query cell size from iTerm2
	t.out = bufio.NewWriter(os.Stdout)
	t.out.WriteString("\x1b]1337;ReportCellSize\x07")
	t.out.Flush()

	// Read response
	origState, err := makeRaw()
	if err != nil {
		return 0, 0, err
	}
	defer restoreRaw(origState)

	resp := readUntilBEL()
	// Parse: ESC]1337;ReportCellSize=H;W BEL
	if idx := strings.Index(resp, "ReportCellSize="); idx >= 0 {
		parts := strings.Split(resp[idx+len("ReportCellSize="):], ";")
		if len(parts) >= 2 {
			h, _ := strconv.ParseFloat(strings.TrimRight(parts[0], "\x07"), 64)
			w, _ := strconv.ParseFloat(strings.TrimRight(parts[1], "\x07"), 64)
			t.cellH = h
			t.cellW = w
		}
	}

	if t.cellH == 0 || t.cellW == 0 {
		// Fallback: use pixel dimensions from TIOCGWINSZ
		ws, err := getWinsize()
		if err == nil && ws.Xpixel > 0 && ws.Ypixel > 0 {
			t.cellW = float64(ws.Xpixel) / float64(ws.Col)
			t.cellH = float64(ws.Ypixel) / float64(ws.Row)
		} else {
			t.cellW = 8
			t.cellH = 15
		}
	}

	imgW := int(t.cellW * float64(cols))
	numRows := rowsFlag
	if numRows == 0 {
		numRows = rows
	}
	imgH := int(t.cellH * float64(numRows))

	return imgW, imgH, nil
}

func (t *ITerm2Terminal) Setup(numRows int) {
	out := bufio.NewWriter(os.Stdout)
	// Hide cursor
	out.WriteString("\x1b[?25l")
	// Move down numRows lines
	for i := 0; i < numRows; i++ {
		out.WriteString("\r\n")
	}
	// Move cursor back up
	fmt.Fprintf(out, "\x1b[%dA", numRows)
	// Save cursor position
	out.WriteString("\x1b[s")
	out.Flush()
	t.out = out
}

func (t *ITerm2Terminal) DisplayImage(imgData []byte, w, h int) error {
	encoded := base64.StdEncoding.EncodeToString(imgData)
	header := fmt.Sprintf("\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:", w, h)

	out := bufio.NewWriter(os.Stdout)
	out.WriteString(header)
	out.WriteString(encoded)
	out.WriteString("\x07")
	// Restore cursor and save again
	out.WriteString("\x1b[u")
	out.WriteString("\x1b[s")
	out.Flush()
	return nil
}

func (t *ITerm2Terminal) Cleanup(numRows int) {
	out := bufio.NewWriter(os.Stdout)
	// Show cursor
	out.WriteString("\x1b[?25h")
	// Move cursor down numRows
	fmt.Fprintf(out, "\x1b[%dB", numRows)
	out.WriteString("\r\n")
	out.Flush()
}

// Kitty Terminal implementation
type KittyTerminal struct {
	detected bool
	imgIDCounter int
	cellW int
	cellH int
}

var kittyBuffer *bufio.Reader

func (t *KittyTerminal) querySupport() bool {
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
	out.Flush()

	origState, err := makeRaw()
	if err != nil {
		return false
	}
	defer restoreRaw(origState)

	// Read response with timeout
	ch := make(chan string, 1)
	if kittyBuffer == nil {
		kittyBuffer = bufio.NewReader(os.Stdin)
	}
	go func() {
		var response strings.Builder
		// Read until ESC\
		for {
			b, err := kittyBuffer.ReadByte()
			if err != nil {
				break
			}
			response.WriteByte(b)
			if b == '\\' && strings.HasSuffix(response.String(), "\x1b\\") {
				break
			}
		}
		ch <- response.String()
	}()

	select {
	case resp := <-ch:
		// Check for error: ESC_Gi=1,e=0 ESC\
		if strings.Contains(resp, "e=0") {
			t.detected = true
			return true
		}
		return false
	case <-time.After(500 * time.Millisecond):
		return false
	}
}

func (t *KittyTerminal) GetSize() (cols, rows int, err error) {
	ws, err := getWinsize()
	if err != nil {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Col), int(ws.Row), nil
}

func (t *KittyTerminal) GetPixelSize(cols, rows, rowsFlag int) (int, int, error) {
	// First query terminal capabilities via ESC[c
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b[c")
	out.Flush()

	origState, err := makeRaw()
	if err != nil {
		return 0, 0, err
	}
	defer restoreRaw(origState)

	// Read ESC[?...c response
	resp := readUntilChar('c')
	_ = resp

	// Then query pixel window size via ESC[14t
	out2 := bufio.NewWriter(os.Stdout)
	out2.WriteString("\x1b[14t")
	out2.Flush()

	// Read ESC[4;<H>;<W>t response
	pixResp := readUntilChar('t')
	// Parse: ESC[4;H;W t
	if idx := strings.Index(pixResp, "4;"); idx >= 0 {
		parts := strings.Split(pixResp[idx+2:], ";")
		if len(parts) >= 2 {
			ph, _ := strconv.Atoi(strings.TrimSuffix(parts[0], "t"))
			pw, _ := strconv.Atoi(strings.TrimSuffix(parts[1], "t"))
			if cols > 0 && rows > 0 {
				t.cellW = pw / cols
				t.cellH = ph / rows
			}
		}
	}

	if t.cellW == 0 {
		t.cellW = 8
	}
	if t.cellH == 0 {
		t.cellH = 15
	}

	imgW := (cols - 1) * t.cellW
	numRows := rowsFlag
	if numRows == 0 {
		imgH := (rows - 1) * t.cellH
		return imgW, imgH, nil
	}
	imgH := numRows * (t.cellH - 1)
	return imgW, imgH, nil
}

func (t *KittyTerminal) Setup(numRows int) {
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b[?25l")
	for i := 0; i < numRows; i++ {
		out.WriteString("\r\n")
	}
	fmt.Fprintf(out, "\x1b[%dA", numRows)
	out.WriteString("\x1b[s")
	out.Flush()
	t.imgIDCounter = 0
}

func (t *KittyTerminal) DisplayImage(imgData []byte, w, h int) error {
	t.imgIDCounter++
	imgID := (t.imgIDCounter % 2) + 1

	encoded := base64.StdEncoding.EncodeToString(imgData)
	params := fmt.Sprintf("a=T,f=100,t=d,i=%d,X=0,Y=0,q=2", imgID)

	out := bufio.NewWriter(os.Stdout)
	// Send in chunks of 4096 characters
	chunkSize := 4096
	header := fmt.Sprintf("\x1b_G%s;", params)

	fullPayload := []byte(header + encoded[:min(chunkSize, len(encoded))] + "\x1b\\")
	out.Write(fullPayload)

	// Remaining chunks
	for i := chunkSize; i < len(encoded); i += chunkSize {
		end := i + chunkSize
		if end > len(encoded) {
			end = len(encoded)
		}
		chunk := fmt.Sprintf("\x1b_G;%s\x1b\\", encoded[i:end])
		out.WriteString(chunk)
	}

	out.WriteString("\x1b[s")
	out.Flush()
	return nil
}

func (t *KittyTerminal) Cleanup(numRows int) {
	imgID := ((t.imgIDCounter-1) % 2) + 1

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintf(out, "\x1b_Ga=d,d=i,i=%d,q=2\x1b\\", imgID)
	out.WriteString("\x1b[u")
	out.WriteString("\x1b[?25h")
	fmt.Fprintf(out, "\x1b[%dB", numRows)
	out.WriteString("\r\n")
	out.Flush()
}

