// Helper functions for terminal I/O
func readUntilBEL() string {
	if kittyBuffer == nil {
		kittyBuffer = bufio.NewReader(os.Stdin)
	}
	var sb strings.Builder
	ch := make(chan string, 1)
	go func() {
		for {
			b, err := kittyBuffer.ReadByte()
			if err != nil {
				break
			}
			sb.WriteByte(b)
			if b == '\x07' {
				break
			}
		}
		ch <- sb.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(500 * time.Millisecond):
		return ""
	}
}

func readUntilChar(term byte) string {
	if kittyBuffer == nil {
		kittyBuffer = bufio.NewReader(os.Stdin)
	}
	var sb strings.Builder
	ch := make(chan string, 1)
	go func() {
		for {
			b, err := kittyBuffer.ReadByte()
			if err != nil {
				break
			}
			sb.WriteByte(b)
			if b == term {
				break
			}
		}
		ch <- sb.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(500 * time.Millisecond):
		return ""
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
