// Terminal interface
type Terminal interface {
	GetSize() (cols, rows int, err error)
	GetPixelSize(cols, rows, rowsFlag int) (w, h int, err error)
	Setup(numRows int)
	DisplayImage(imgData []byte, w, h int) error
	Cleanup(numRows int)
}

// Winsize for ioctl
type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinsize() (Winsize, error) {
	var ws Winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(0x5413), // TIOCGWINSZ
		uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return ws, errno
	}
	return ws, nil
}

// Terminal detection
func detectTerminal() (Terminal, error) {
	// First try to query Kitty support
	kittyTerm := &KittyTerminal{}
	if ok := kittyTerm.querySupport(); ok {
		return kittyTerm, nil
	}

	// Check TERM_PROGRAM for iTerm2 or other supported terminals
	termProg := os.Getenv("TERM_PROGRAM")
	switch termProg {
	case "iTerm.app":
		return &ITerm2Terminal{}, nil
	case "WarpTerminal", "Hyper":
		// These support iTerm2 protocol
		return &ITerm2Terminal{}, nil
	}

	// Try querying terminal via ESC[c (Device Attributes)
	if hasSixel, hasKitty := queryTerminalCapabilities(); hasKitty {
		_ = hasSixel
		kittyTerm2 := &KittyTerminal{}
		kittyTerm2.detected = true
		return kittyTerm2, nil
	} else if hasSixel {
		return &SixelTerminal{}, nil
	}

	return nil, fmt.Errorf("iTerm2, Kitty, or DRCS Sixel graphics required")
}

// queryTerminalCapabilities sends ESC[c and reads response
func queryTerminalCapabilities() (hasSixel, hasKitty bool) {
	// Set stdin to raw mode temporarily
	origState, err := makeRaw()
	if err != nil {
		return false, false
	}
	defer restoreRaw(origState)

	// Send Primary DA request
	fmt.Fprint(os.Stdout, "\x1b[c")

	// Read response with timeout
	ch := make(chan string, 1)
	go func() {
		reader := bufio.NewReader(os.Stdin)
		var response strings.Builder
		// Wait for ESC[?...c response
		for {
			b, err := reader.ReadByte()
			if err != nil {
				break
			}
			response.WriteByte(b)
			if b == 'c' && response.Len() > 1 {
				break
			}
		}
		ch <- response.String()
	}()

	select {
	case resp := <-ch:
		// Parse response ESC[?62;...c
		if strings.Contains(resp, "?") {
			params := resp[strings.Index(resp, "?")+1:]
			params = strings.TrimSuffix(params, "c")
			for _, p := range strings.Split(params, ";") {
				n, _ := strconv.Atoi(p)
				if n == 4 { // Sixel support
					hasSixel = true
				}
			}
		}
	case <-time.After(500 * time.Millisecond):
	}

	return hasSixel, false
}

