func (t *KittyTerminal) querySupport() bool {
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
	out.Flush()

	origState, err := makeRaw()
	if err != nil {
		return false
	}
	defer restoreRaw(origState)

	// Read response with timeout
	ch := make(chan string, 1)
	if kittyBuffer == nil {
		kittyBuffer = bufio.NewReader(os.Stdin)
	}
	go func() {
		var response strings.Builder
		// Read until ESC\
		for {
			b, err := kittyBuffer.ReadByte()
			if err != nil {
				break
			}
			response.WriteByte(b)
			if b == '\\' && strings.HasSuffix(response.String(), "\x1b\\") {
				break
			}
		}
		ch <- response.String()
	}()

	select {
	case resp := <-ch:
		// Check for error: ESC_Gi=1,e=0 ESC\
		if strings.Contains(resp, "e=0") {
			t.detected = true
			return true
		}
		return false
	case <-time.After(500 * time.Millisecond):
		return false
	}
}

