func (t *KittyTerminal) GetPixelSize(cols, rows, rowsFlag int) (int, int, error) {
	// First query terminal capabilities via ESC[c
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b[c")
	out.Flush()

	origState, err := makeRaw()
	if err != nil {
		return 0, 0, err
	}
	defer restoreRaw(origState)

	// Read ESC[?...c response
	resp := readUntilChar('c')
	_ = resp

	// Then query pixel window size via ESC[14t
	out2 := bufio.NewWriter(os.Stdout)
	out2.WriteString("\x1b[14t")
	out2.Flush()

	// Read ESC[4;<H>;<W>t response
	pixResp := readUntilChar('t')
	// Parse: ESC[4;H;W t
	if idx := strings.Index(pixResp, "4;"); idx >= 0 {
		parts := strings.Split(pixResp[idx+2:], ";")
		if len(parts) >= 2 {
			ph, _ := strconv.Atoi(strings.TrimSuffix(parts[0], "t"))
			pw, _ := strconv.Atoi(strings.TrimSuffix(parts[1], "t"))
			if cols > 0 && rows > 0 {
				t.cellW = pw / cols
				t.cellH = ph / rows
			}
		}
	}

	if t.cellW == 0 {
		t.cellW = 8
	}
	if t.cellH == 0 {
		t.cellH = 15
	}

	imgW := (cols - 1) * t.cellW
	numRows := rowsFlag
	if numRows == 0 {
		imgH := (rows - 1) * t.cellH
		return imgW, imgH, nil
	}
	imgH := numRows * (t.cellH - 1)
	return imgW, imgH, nil
}

