package main

import (
	"bytes"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
)

// Chart colors
var seriesColors = []color.RGBA{
	{R: 0, G: 116, B: 217, A: 255},   // #0074D9 Blue
	{R: 0, G: 217, B: 101, A: 255},   // #00D965 Green
	{R: 217, G: 0, B: 116, A: 255},   // #D90074 Pink
	{R: 0, G: 217, B: 210, A: 255},   // #00D9D2 Teal
	{R: 217, G: 101, B: 0, A: 255},   // #D96500 Orange
	{R: 127, G: 219, B: 255, A: 255}, // #7FDBFF Aqua
	{R: 46, G: 204, B: 64, A: 255},   // #2ECC40 Green2
}

var axisColor = color.RGBA{R: 179, G: 179, B: 179, A: 128}
var axisColorFull = color.RGBA{R: 179, G: 179, B: 179, A: 255}
var textColor = color.RGBA{R: 51, G: 51, B: 51, A: 255}

// Image canvas  
type Canvas struct {
	img *image.RGBA
	W   int
	H   int
}

func newImage(w, h int) *Canvas {
	return &Canvas{
		img: image.NewRGBA(image.Rect(0, 0, w, h)),
		W:   w,
		H:   h,
	}
}

func encodePNG(c *Canvas) []byte {
	var buf bytes.Buffer
	_ = png.Encode(&buf, c.img)
	return buf.Bytes()
}

// Blend a color with alpha onto the canvas
func (c *Canvas) setPixel(x, y int, col color.RGBA) {
	if x < 0 || y < 0 || x >= c.W || y >= c.H {
		return
	}
	// Alpha compositing: src over dst
	src := col
	dst := c.img.RGBAAt(x, y)

	if dst.A == 0 {
		c.img.SetRGBA(x, y, src)
		return
	}

	srcA := float64(src.A) / 255.0
	dstA := float64(dst.A) / 255.0
	outA := srcA + dstA*(1-srcA)
	if outA < 1e-9 {
		return
	}

	outR := (srcA*float64(src.R) + dstA*(1-srcA)*float64(dst.R)) / outA
	outG := (srcA*float64(src.G) + dstA*(1-srcA)*float64(dst.G)) / outA
	outB := (srcA*float64(src.B) + dstA*(1-srcA)*float64(dst.B)) / outA

	c.img.SetRGBA(x, y, color.RGBA{
		R: uint8(math.Min(255, outR)),
		G: uint8(math.Min(255, outG)),
		B: uint8(math.Min(255, outB)),
		A: uint8(math.Min(255, outA*255)),
	})
}

// Draw an anti-aliased line using Xiaolin Wu's algorithm
func (c *Canvas) drawLineAA(x0, y0, x1, y1 float64, col color.RGBA) {
	steep := math.Abs(y1-y0) > math.Abs(x1-x0)
	if steep {
		x0, y0 = y0, x0
		x1, y1 = y1, x1
	}
	if x0 > x1 {
		x0, x1 = x1, x0
		y0, y1 = y1, y0
	}

	dx := x1 - x0
	dy := y1 - y0
	gradient := dy / dx
	if dx == 0 {
		gradient = 1
	}

	plot := func(x, y float64, brightness float64) {
		alpha := uint8(float64(col.A) * brightness)
		if alpha == 0 {
