		numPoints = steps
	}

	for si, fs := range gs {
		if fs.Marker {
			continue
		}
		if si >= len(buf) {
			continue
		}
		for i := 0; i < numPoints; i++ {
			pos := (count - numPoints + i) % steps
			v := buf[si][pos]
			if math.IsNaN(v) {
				continue
			}
			if math.IsNaN(minVal) || v < minVal {
				minVal = v
			}
			if math.IsNaN(maxVal) || v > maxVal {
				maxVal = v
			}
		}
