	}

	for si, fs := range gs {
		if fs.Marker {
			continue
		}
		if si >= len(buf) {
			continue
		}
		for i := 0; i < numPoints; i++ {
			pos := (count - numPoints + i) % steps
			v := buf[si][pos]
			if math.IsNaN(v) {
				continue
			}
			if math.IsNaN(minVal) || v < minVal {
				minVal = v
			}
			if math.IsNaN(maxVal) || v > maxVal {
				maxVal = v
			}
		}
	}

	if math.IsNaN(minVal) {
		return 0, 1
	}

	// Add padding
	if minVal > 0 {
		minVal = 0
	}
	padding := (maxVal - minVal) * 0.1
	if padding == 0 {
		padding = 1
	}
	maxVal += padding

	return minVal, maxVal
}

func drawAxis(canvas *Canvas, x0, x1, y0, y1, w int, minVal, maxVal float64) {
	// Draw horizontal grid lines
	numTicks := 8
	for i := 0; i <= numTicks; i++ {
		y := y0 + (y1-y0)*i/numTicks
		// Draw subtle grid line
		gridCol := color.RGBA{R: 179, G: 179, B: 179, A: 20}
		for x := x0; x <= x1; x++ {
			canvas.setPixel(x, y, gridCol)
		}
	}

	// Draw y-axis (right side)
	for y := y0; y <= y1; y++ {
		canvas.setPixel(x1, y, axisColor)
	}

	// Draw x-axis (bottom)
	for x := x0; x <= x1; x++ {
		canvas.setPixel(x, y1, axisColor)
	}
}

func drawSeries(canvas *Canvas, data []float64, count, steps, numPoints, x0, x1, y0, y1, plotW, plotH int, minVal, maxVal float64, col color.RGBA) {
	if numPoints < 1 {
		return
	}

	fillCol := color.RGBA{R: col.R, G: col.G, B: col.B, A: 20}

	prevX := -1.0
	prevY := -1.0

	for i := 0; i < numPoints; i++ {
		pos := (count - numPoints + i) % steps
		v := data[pos]
		if math.IsNaN(v) {
			prevX = -1
			prevY = -1
			continue
		}

		// Map to pixel coordinates
		xf := float64(x0) + float64(i)*float64(plotW)/float64(steps-1)
		yNorm := (v - minVal) / (maxVal - minVal)
		yf := float64(y1) - yNorm*float64(plotH)

		// Fill below the line
		yFillStart := int(yf)
		if yFillStart < y0 {
			yFillStart = y0
		}
		for y := yFillStart; y <= y1; y++ {
			canvas.setPixel(int(xf), y, fillCol)
		}

		// Draw line segment
		if prevX >= 0 {
			canvas.drawLineAA(prevX, prevY, xf, yf, col)
		}

		prevX = xf
		prevY = yf
	}
}

func drawMarker(canvas *Canvas, data []float64, count, steps, numPoints, x0, x1, y0, y1, plotW, plotH int) {
	markerCol := color.RGBA{R: 50, G: 50, B: 50, A: 128}
	for i := 0; i < numPoints; i++ {
		pos := (count - numPoints + i) % steps
		v := data[pos]
		if math.IsNaN(v) || v == 0 {
			continue
		}
		xf := int(float64(x0) + float64(i)*float64(plotW)/float64(steps-1))
		for y := y0; y <= y1; y++ {
			canvas.setPixel(xf, y, markerCol)
		}
	}
}

func drawXAxisLabels(canvas *Canvas, x0, x1, y1, count, steps int) {
	// Draw tick marks every 1/8 of the range
	numTicks := 8
	plotW := x1 - x0

	numPoints := count
	if numPoints > steps {
		numPoints = steps
	}

	for i := 0; i <= numTicks; i++ {
		xf := x0 + plotW*i/numTicks
		// Tick mark
		for y := y1; y <= y1+4; y++ {
			canvas.setPixel(xf, y, axisColor)
		}
	}

	// Labels: show step indices
	// Space for ~3 character labels
	numLabels := 9
	labelStep := numPoints / (numLabels - 1)
	if labelStep < 1 {
		labelStep = 1
	}

	for i := 0; i < numLabels; i++ {
		idx := i * labelStep
		if idx >= numPoints {
			idx = numPoints - 1
		}
		stepNum := count - numPoints + idx
		label := fmt.Sprintf("%d", stepNum)

		xf := x0 + plotW*idx/(numPoints-1)
		// Center the label
		textW := len(label) * 6
		textX := xf - textW/2
		drawText(canvas, label, textX, y1+6, textColor)
	}
}

func drawYAxisLabels(canvas *Canvas, x1, y0, y1, canvasW int, minVal, maxVal float64) {
	numTicks := 8
	plotH := y1 - y0

	for i := 0; i <= numTicks; i++ {
		yf := y0 + plotH*i/numTicks
		val := maxVal - (maxVal-minVal)*float64(i)/float64(numTicks)

		// Tick mark (extending right from axis)
		for x := x1; x <= x1+4; x++ {
			canvas.setPixel(x, yf, axisColor)
		}

		// Label
		label := formatValue(val)
		textX := x1 + 6
		textY := yf - 5
		if textY < y0 {
			textY = y0
		}
		drawText(canvas, label, textX, textY, textColor)
	}
}

func formatValue(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "N/A"
	}
	abs := math.Abs(v)
	if abs >= 1e9 {
		return fmt.Sprintf("%.2gG", v/1e9)
	} else if abs >= 1e6 {
		return fmt.Sprintf("%.2gM", v/1e6)
	} else if abs >= 1e3 {
		return fmt.Sprintf("%.2gk", v/1e3)
	} else if abs >= 100 {
		return fmt.Sprintf("%.0f", v)
	} else if abs >= 10 {
		return fmt.Sprintf("%.1f", v)
	} else if abs >= 1 {
		return fmt.Sprintf("%.2f", v)
	} else if abs > 0 {
		return fmt.Sprintf("%.3f", v)
	}
	return "0.00"
}
