package main

import (
	"bufio"
	"encoding/base64"
	"fmt"
	"os"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

// Terminal interface
type Terminal interface {
	GetSize() (cols, rows int, err error)
	GetPixelSize(cols, rows, rowsFlag int) (w, h int, err error)
	Setup(numRows int)
	DisplayImage(imgData []byte, w, h int) error
	Cleanup(numRows int)
}

// Winsize for ioctl
type Winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

// Global TTY for terminal I/O
var tty *os.File
var ttyReader *bufio.Reader

func openTTY() error {
	var err error
	tty, err = os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		// Fallback: use stdout for writing and stdin for reading
		// when stdin is actually a terminal
		if isTerminal(os.Stdin.Fd()) {
			tty = os.Stdin
		} else if isTerminal(os.Stdout.Fd()) {
			// We'll handle this case separately
			tty = nil
			return nil
		} else {
			return err
		}
	}
	ttyReader = bufio.NewReader(tty)
	return nil
}

func isTerminal(fd uintptr) bool {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd,
		uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(new(Winsize))))
	return errno == 0
}

func getWinsize() (Winsize, error) {
	var ws Winsize
	// Try stdout first, then tty
	fds := []uintptr{os.Stdout.Fd()}
	if tty != nil {
		fds = append(fds, tty.Fd())
	}
	for _, fd := range fds {
		_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd,
			uintptr(0x5413), // TIOCGWINSZ
			uintptr(unsafe.Pointer(&ws)))
		if errno == 0 {
			return ws, nil
		}
	}
	return ws, fmt.Errorf("inappropriate ioctl for device")
}

// Terminal detection
func detectTerminal() (Terminal, error) {
	err := openTTY()
	if err != nil && tty == nil {
		// Cannot open tty - can't display graphics
		// But try TERM_PROGRAM first
	}

	// Check TERM_PROGRAM for iTerm2
	termProg := os.Getenv("TERM_PROGRAM")
	if termProg == "iTerm.app" {
		return &ITerm2Terminal{}, nil
	}

	// Check KITTY_WINDOW_ID
	if os.Getenv("KITTY_WINDOW_ID") != "" {
		return &KittyTerminal{detected: true}, nil
	}

	// Check TERM_PROGRAM for other iTerm2-compatible terminals
	switch termProg {
	case "WarpTerminal":
		// Warp supports both iTerm2 and Kitty protocols
		// Try Kitty first
		kittyTerm := &KittyTerminal{}
		if kittyTerm.querySupport() {
			return kittyTerm, nil
		}
		return &ITerm2Terminal{}, nil
	}

	// Try Kitty protocol query
	kittyTerm := &KittyTerminal{}
	if kittyTerm.querySupport() {
		return kittyTerm, nil
	}

	// Try ESC[c for capabilities
	if hasSixel := queryDA(); hasSixel {
		return &SixelTerminal{}, nil
	}

	return nil, fmt.Errorf("iTerm2, Kitty, or DRCS Sixel graphics required")
}

// queryDA sends ESC[c and checks for Sixel in response
func queryDA() bool {
	origState, err := makeRaw()
	if err != nil {
		return false
	}
	defer restoreRaw(origState)

	fmt.Fprint(os.Stdout, "\x1b[c")

	resp := readTTYUntil('c', 500*time.Millisecond)
	if strings.Contains(resp, "?") {
		params := resp[strings.Index(resp, "?")+1:]
		params = strings.TrimSuffix(params, "c")
		for _, p := range strings.Split(params, ";") {
			n, _ := strconv.Atoi(p)
			if n == 4 {
				return true
			}
		}
	}
	return false
}

// readTTYUntil reads from tty until terminator byte or timeout
func readTTYUntil(term byte, timeout time.Duration) string {
	ch := make(chan string, 1)
	go func() {
		var sb strings.Builder
		r := ttyReader
		if r == nil {
			r = bufio.NewReader(os.Stdin)
		}
		for {
			b, err := r.ReadByte()
			if err != nil {
				break
			}
			sb.WriteByte(b)
			if b == term {
				break
			}
		}
		ch <- sb.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(timeout):
		return ""
	}
}

func readTTYUntilBEL(timeout time.Duration) string {
	ch := make(chan string, 1)
	go func() {
		var sb strings.Builder
		r := ttyReader
		if r == nil {
			r = bufio.NewReader(os.Stdin)
		}
		for {
			b, err := r.ReadByte()
			if err != nil {
				break
			}
			sb.WriteByte(b)
			if b == '\x07' {
				break
			}
		}
		ch <- sb.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(timeout):
		return ""
	}
}

func readTTYUntilESCBackslash(timeout time.Duration) string {
	ch := make(chan string, 1)
	go func() {
		var sb strings.Builder
		r := ttyReader
		if r == nil {
			r = bufio.NewReader(os.Stdin)
		}
		for {
			b, err := r.ReadByte()
			if err != nil {
				break
			}
			sb.WriteByte(b)
			if b == '\\' && strings.HasSuffix(sb.String(), "\x1b\\") {
				break
			}
		}
		ch <- sb.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(timeout):
		return ""
	}
}

// iTerm2 Terminal implementation
type ITerm2Terminal struct {
	cellW float64
	cellH float64
}

func (t *ITerm2Terminal) GetSize() (cols, rows int, err error) {
	ws, err := getWinsize()
	if err != nil {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Col), int(ws.Row), nil
}

func (t *ITerm2Terminal) GetPixelSize(cols, rows, rowsFlag int) (int, int, error) {
	// Query cell size from iTerm2
	origState, err := makeRaw()
	if err == nil {
		defer restoreRaw(origState)
	}

	fmt.Fprint(os.Stdout, "\x1b]1337;ReportCellSize\x07")

	resp := readTTYUntilBEL(500 * time.Millisecond)
	// Parse: ESC]1337;ReportCellSize=H;W BEL
	if idx := strings.Index(resp, "ReportCellSize="); idx >= 0 {
		parts := strings.Split(resp[idx+len("ReportCellSize="):], ";")
		if len(parts) >= 2 {
			h, _ := strconv.ParseFloat(strings.TrimRight(parts[0], "\x07"), 64)
			w, _ := strconv.ParseFloat(strings.TrimRight(parts[1], "\x07"), 64)
			t.cellH = h
			t.cellW = w
		}
	}

	if t.cellH == 0 || t.cellW == 0 {
		// Fallback: use pixel dimensions from TIOCGWINSZ
		ws, err := getWinsize()
		if err == nil && ws.Xpixel > 0 && ws.Ypixel > 0 {
			t.cellW = float64(ws.Xpixel) / float64(ws.Col)
			t.cellH = float64(ws.Ypixel) / float64(ws.Row)
		} else {
			t.cellW = 8
			t.cellH = 15
		}
	}

	imgW := int(t.cellW * float64(cols))
	numRows := rowsFlag
	if numRows == 0 {
		numRows = rows
	}
	imgH := int(t.cellH * float64(numRows))

	return imgW, imgH, nil
}

func (t *ITerm2Terminal) Setup(numRows int) {
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b[?25l")
	for i := 0; i < numRows; i++ {
		out.WriteString("\r\n")
	}
	fmt.Fprintf(out, "\x1b[%dA", numRows)
	out.WriteString("\x1b[s")
	out.Flush()
}

func (t *ITerm2Terminal) DisplayImage(imgData []byte, w, h int) error {
	encoded := base64.StdEncoding.EncodeToString(imgData)
	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintf(out, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:", w, h)
	out.WriteString(encoded)
	out.WriteString("\x07")
	out.WriteString("\x1b[u")
	out.WriteString("\x1b[s")
	out.Flush()
	return nil
}

func (t *ITerm2Terminal) Cleanup(numRows int) {
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b[?25h")
	fmt.Fprintf(out, "\x1b[%dB", numRows)
	out.WriteString("\r\n")
	out.Flush()
}

// Kitty Terminal implementation
type KittyTerminal struct {
	detected     bool
	imgIDCounter int
	cellW        int
	cellH        int
}

func (t *KittyTerminal) querySupport() bool {
	origState, err := makeRaw()
	if err != nil {
		return false
	}
	defer restoreRaw(origState)

	fmt.Fprint(os.Stdout, "\x1b_Gi=1,a=q,t=d,f=24\x1b\\")

	resp := readTTYUntilESCBackslash(500 * time.Millisecond)
	if strings.Contains(resp, "e=0") {
		t.detected = true
		return true
	}
	return false
}

func (t *KittyTerminal) GetSize() (cols, rows int, err error) {
	ws, err := getWinsize()
	if err != nil {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Col), int(ws.Row), nil
}

func (t *KittyTerminal) GetPixelSize(cols, rows, rowsFlag int) (int, int, error) {
	origState, err := makeRaw()
	if err == nil {
		defer restoreRaw(origState)
	}

