	origState, err := makeRaw()
	if err != nil {
		return false
	}
	defer restoreRaw(origState)

	fmt.Fprint(os.Stdout, "\x1b_Gi=1,a=q,t=d,f=24\x1b\\")

	resp := readTTYUntilESCBackslash(500 * time.Millisecond)
	if strings.Contains(resp, "e=0") {
		t.detected = true
		return true
	}
	return false
