}

// Kitty Terminal implementation
type KittyTerminal struct {
	detected     bool
	imgIDCounter int
	cellW        int
	cellH        int
}

func (t *KittyTerminal) querySupport() bool {
	origState, err := makeRaw()
	if err != nil {
		return false
	}
	defer restoreRaw(origState)

	fmt.Fprint(os.Stdout, "\x1b_Gi=1,a=q,t=d,f=24\x1b\\")

	resp := readTTYUntilESCBackslash(500 * time.Millisecond)
	if strings.Contains(resp, "e=0") {
		t.detected = true
		return true
	}
	return false
}

func (t *KittyTerminal) GetSize() (cols, rows int, err error) {
	ws, err := getWinsize()
	if err != nil {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Col), int(ws.Row), nil
}

func (t *KittyTerminal) GetPixelSize(cols, rows, rowsFlag int) (int, int, error) {
	origState, err := makeRaw()
	if err == nil {
		defer restoreRaw(origState)
	}

	// Query terminal capabilities first
	fmt.Fprint(os.Stdout, "\x1b[c")
	readTTYUntil('c', 500*time.Millisecond)

	// Query pixel window size
	fmt.Fprint(os.Stdout, "\x1b[14t")
	pixResp := readTTYUntil('t', 500*time.Millisecond)

	// Parse: ESC[4;H;Wt
	if idx := strings.Index(pixResp, "4;"); idx >= 0 {
		parts := strings.Split(pixResp[idx+2:], ";")
		if len(parts) >= 2 {
			ph, _ := strconv.Atoi(strings.TrimSuffix(parts[0], "t"))
			pw, _ := strconv.Atoi(strings.TrimSuffix(strings.TrimRight(parts[1], "t"), "t"))
			if cols > 0 && rows > 0 && ph > 0 && pw > 0 {
				t.cellW = pw / cols
				t.cellH = ph / rows
			}
		}
	}

	if t.cellW == 0 {
		ws, err := getWinsize()
		if err == nil && ws.Xpixel > 0 && ws.Col > 0 {
			t.cellW = int(ws.Xpixel) / int(ws.Col)
			t.cellH = int(ws.Ypixel) / int(ws.Row)
		} else {
			t.cellW = 8
			t.cellH = 15
		}
	}

	imgW := (cols - 1) * t.cellW
	numRows := rowsFlag
	if numRows == 0 {
		imgH := (rows - 1) * t.cellH
		return imgW, imgH, nil
	}
	imgH := numRows * (t.cellH - 1)
	return imgW, imgH, nil
}

func (t *KittyTerminal) Setup(numRows int) {
	out := bufio.NewWriter(os.Stdout)
	out.WriteString("\x1b[?25l")
	for i := 0; i < numRows; i++ {
		out.WriteString("\r\n")
	}
	fmt.Fprintf(out, "\x1b[%dA", numRows)
	out.WriteString("\x1b[s")
	out.Flush()
	t.imgIDCounter = 0
}

func (t *KittyTerminal) DisplayImage(imgData []byte, w, h int) error {
	t.imgIDCounter++
	imgID := (t.imgIDCounter-1)%2 + 1
	_ = w
	_ = h

	encoded := base64.StdEncoding.EncodeToString(imgData)
	params := fmt.Sprintf("a=T,f=100,t=d,i=%d,X=0,Y=0,q=2", imgID)

	out := bufio.NewWriter(os.Stdout)
	chunkSize := 4096

	// First chunk
	end := chunkSize
	if end > len(encoded) {
		end = len(encoded)
	}
	fmt.Fprintf(out, "\x1b_G%s;%s\x1b\\", params, encoded[:end])

	// Remaining chunks
	for i := end; i < len(encoded); i += chunkSize {
		chunkEnd := i + chunkSize
		if chunkEnd > len(encoded) {
			chunkEnd = len(encoded)
		}
		fmt.Fprintf(out, "\x1b_G;%s\x1b\\", encoded[i:chunkEnd])
	}

	out.WriteString("\x1b[s")
	out.Flush()
	return nil
}

func (t *KittyTerminal) Cleanup(numRows int) {
	// Delete the other alternating image
	otherID := (t.imgIDCounter % 2) + 1

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintf(out, "\x1b_Ga=d,d=i,i=%d,q=2\x1b\\", otherID)
	out.WriteString("\x1b[u")
	out.WriteString("\x1b[?25h")
	fmt.Fprintf(out, "\x1b[%dB", numRows)
	out.WriteString("\r\n")
	out.Flush()
}

