# When we fork, /dev/tty refers to the CONTROLLING TERMINAL of the process
# The subprocess was created with stdin as a pipe but stdout as the pty slave
# So /dev/tty should be the pty slave

# But wait - the pty slave is the TTY for the subprocess's process group
# Opening /dev/tty from the subprocess should give the pty slave fd

# The issue might be that when we:
# 1. Write ESC]1337;ReportCellSize to stdout (pty slave)
# 2. This goes to the pty master (which we control)
# 3. We write the response to pty master
# 4. The subprocess reads from /dev/tty (pty slave) and gets the response

# This SHOULD work! Let me check if the issue is in raw mode setup

# Let me add a debug version
cat > /tmp/debug_jplot.go << 'GOEOF'
package main

import (
	"bufio"
	"fmt"
	"os"
	"time"
	"strings"
)

var ttyFile *os.File

func main() {
	var err error
	ttyFile, err = os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Cannot open /dev/tty:", err)
		os.Exit(1)
	}

	fmt.Fprintln(os.Stderr, "Opened /dev/tty")

	// Send query to stdout
	fmt.Fprint(os.Stdout, "\x1b]1337;ReportCellSize\x07")
	os.Stdout.Sync()

	fmt.Fprintln(os.Stderr, "Sent ReportCellSize query")

	// Read from tty
	ttyReader := bufio.NewReader(ttyFile)
	ch := make(chan string, 1)
	go func() {
		var sb strings.Builder
		for {
			b, err := ttyReader.ReadByte()
			if err != nil {
				fmt.Fprintln(os.Stderr, "Read error:", err)
				break
			}
			sb.WriteByte(b)
			if b == '\x07' {
				break
			}
		}
		ch <- sb.String()
	}()

	select {
	case resp := <-ch:
		fmt.Fprintln(os.Stderr, "Got response:", resp)
	case <-time.After(2*time.Second):
		fmt.Fprintln(os.Stderr, "Timeout waiting for response")
	}

	// Read stdin
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		fmt.Fprintln(os.Stderr, "Stdin:", scanner.Text())
	}
}
