package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"math"
	"net/http"
	"os"
	"strings"
	"time"
)

var (
	flagURL      string
	flagInterval time.Duration
	flagSteps    int
	flagRows     int
)

func main() {
	flag.StringVar(&flagURL, "url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
	flag.DurationVar(&flagInterval, "interval", time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
	flag.IntVar(&flagSteps, "steps", 100, "Number of values to plot.")
	flag.IntVar(&flagRows, "rows", 0, "Limits the height of the graph output.")
	flag.Usage = usage
	flag.Parse()

	if flag.NArg() == 0 {
		fmt.Fprint(os.Stderr, "jplot:  neither --url nor stdin is provided\n")
		os.Exit(1)
	}

	// Parse field specs
	specs, err := parseFieldSpecs(flag.Args())
	if err != nil {
		fmt.Fprintf(os.Stderr, "jplot:  %v\n", err)
		os.Exit(1)
	}

	// Detect terminal
	term, err := detectTerminal()
	if err != nil {
		fmt.Fprintf(os.Stderr, "jplot:  %v\n", err)
		os.Exit(1)
	}

	// Get terminal dimensions
	cols, rows, err := term.GetSize()
	if err != nil {
		fmt.Fprintf(os.Stderr, "jplot:  Cannot get window size:  %v\n", err)
		os.Exit(1)
	}

	// Get pixel dimensions (queries cell size from terminal)
	imgW, imgH, err := term.GetPixelSize(cols, rows, flagRows)
	if err != nil {
		fmt.Fprintf(os.Stderr, "jplot:  Cannot get pixel size: %v\n", err)
		os.Exit(1)
	}

	numRows := flagRows
	if numRows == 0 {
		numRows = rows
	}

	// Create data source
	var dataCh <-chan map[string]interface{}
	var errCh <-chan error
	if flagURL != "" {
		dataCh, errCh = urlDataSource(flagURL, flagInterval)
	} else {
		dataCh, errCh = stdinDataSource()
	}

	// Initialize plot state
	plotState := newPlotState(specs, flagSteps)

	// Terminal setup (hide cursor, scroll, save position)
	term.Setup(numRows)

	// Render loop
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	needRender := false
	done := false

	for !done {
		select {
		case data, ok := <-dataCh:
			if !ok {
				done = true
				break
			}
			plotState.AddData(data)
			needRender = true
		case err = <-errCh:
			if err != nil && err != io.EOF {
				// Store error to show after cleanup
				done = true
				_ = err
				break
			}
			done = true
		case <-ticker.C:
			if needRender {
				img := plotState.Render(imgW, imgH)
				if err2 := term.DisplayImage(img, imgW, imgH, false); err2 != nil {
					done = true
					break
				}
				needRender = false
			}
		}
	}

	// Final render if needed
	if needRender {
		img := plotState.Render(imgW, imgH)
		_ = term.DisplayImage(img, imgW, imgH, true)
	}

	term.Cleanup(numRows)

	// Show data source error if any
	if err != nil && err != io.EOF {
		fmt.Fprintf(os.Stderr, "jplot:  Data source error:  %v\n", err)
	}
}

func usage() {
	fmt.Fprint(os.Stderr, `Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:

OPTIONS:
  -interval duration
    	When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)
  -rows int
    	Limits the height of the graph output.
  -steps int
    	Number of values to plot. (default 100)
  -url string
    	URL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
`)
}

// FieldSpec represents one data series spec
type FieldSpec struct {
	Path    string
	Counter bool
	Marker  bool
}

// GraphSpec groups multiple field specs for one graph
type GraphSpec []FieldSpec

func parseFieldSpecs(args []string) ([]GraphSpec, error) {
	var result []GraphSpec
	for _, arg := range args {
		parts := strings.Split(arg, "+")
		var graphSpec GraphSpec
		for _, part := range parts {
			fs, err := parseOneSeries(part)
			if err != nil {
				return nil, err
			}
			graphSpec = append(graphSpec, fs)
		}
		result = append(result, graphSpec)
	}
	return result, nil
}

func parseOneSeries(s string) (FieldSpec, error) {
	fs := FieldSpec{}
	idx := strings.Index(s, ":")
	if idx >= 0 {
		optStr := s[:idx]
		fs.Path = s[idx+1:]
		opts := strings.Split(optStr, ",")
		for _, opt := range opts {
			switch opt {
			case "counter":
				fs.Counter = true
			case "marker":
				fs.Marker = true
			default:
				return fs, fmt.Errorf("unknown option: %s", opt)
			}
		}
	} else {
		fs.Path = s
	}
	return fs, nil
}

// getJSONValue navigates a dot-separated path in a JSON object
func getJSONValue(data map[string]interface{}, path string) (float64, bool) {
	parts := strings.Split(path, ".")
	var current interface{} = data
	for _, part := range parts {
		m, ok := current.(map[string]interface{})
		if !ok {
			return 0, false
		}
		current, ok = m[part]
		if !ok {
			return 0, false
		}
	}
	switch v := current.(type) {
	case float64:
		return v, true
	case int:
		return float64(v), true
	case int64:
		return float64(v), true
	default:
		return 0, false
	}
}

// PlotState manages data buffers and rendering
type PlotState struct {
	specs   []GraphSpec
	steps   int
	buffers [][][]float64
	prevs   [][]float64
	counts  []int
}

func newPlotState(specs []GraphSpec, steps int) *PlotState {
	ps := &PlotState{
		specs: specs,
		steps: steps,
	}
	for _, gs := range specs {
		var graphBuf [][]float64
		var prevRow []float64
		for range gs {
			graphBuf = append(graphBuf, make([]float64, steps))
			prevRow = append(prevRow, math.NaN())
		}
		ps.buffers = append(ps.buffers, graphBuf)
		ps.prevs = append(ps.prevs, prevRow)
		ps.counts = append(ps.counts, 0)
	}
	return ps
