package main

import (
	"bytes"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
)

// Chart colors - matching the original's palette
var seriesColors = []color.RGBA{
	{R: 0, G: 116, B: 217, A: 255},   // #0074D9 Blue
	{R: 0, G: 217, B: 101, A: 255},   // #00D965 Green
	{R: 217, G: 0, B: 116, A: 255},   // #D90074 Pink
	{R: 0, G: 217, B: 210, A: 255},   // #00D9D2 Teal
	{R: 217, G: 101, B: 0, A: 255},   // #D96500 Orange
	{R: 127, G: 219, B: 255, A: 255}, // #7FDBFF Aqua
	{R: 46, G: 204, B: 64, A: 255},   // #2ECC40 Green2
}

var axisColor = color.RGBA{R: 179, G: 179, B: 179, A: 128}
var textColor = color.RGBA{R: 51, G: 51, B: 51, A: 255}

// RGBA image canvas
type Canvas struct {
	img *image.RGBA
	W   int
	H   int
}

func newImage(w, h int) *Canvas {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	return &Canvas{img: img, W: w, H: h}
}

func encodePNG(c *Canvas) []byte {
	var buf bytes.Buffer
	png.Encode(&buf, c.img)
	return buf.Bytes()
}

// Set pixel with alpha compositing (src over dst)
func (c *Canvas) setPixel(x, y int, col color.RGBA) {
	if x < 0 || y < 0 || x >= c.W || y >= c.H {
		return
	}
	if col.A == 0 {
		return
	}
	dst := c.img.RGBAAt(x, y)
	if dst.A == 0 {
		c.img.SetRGBA(x, y, col)
		return
	}

	srcA := float64(col.A) / 255.0
	dstA := float64(dst.A) / 255.0
	outA := srcA + dstA*(1-srcA)
	if outA < 1e-9 {
		return
	}

	c.img.SetRGBA(x, y, color.RGBA{
		R: clamp8((srcA*float64(col.R) + dstA*(1-srcA)*float64(dst.R)) / outA),
		G: clamp8((srcA*float64(col.G) + dstA*(1-srcA)*float64(dst.G)) / outA),
		B: clamp8((srcA*float64(col.B) + dstA*(1-srcA)*float64(dst.B)) / outA),
		A: clamp8(outA * 255),
	})
}

func clamp8(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}

// Anti-aliased line (Xiaolin Wu's algorithm)
func (c *Canvas) drawLineAA(x0, y0, x1, y1 float64, col color.RGBA) {
	steep := math.Abs(y1-y0) > math.Abs(x1-x0)
	if steep {
		x0, y0 = y0, x0
		x1, y1 = y1, x1
	}
	if x0 > x1 {
		x0, x1 = x1, x0
		y0, y1 = y1, y0
	}
	dx := x1 - x0
	dy := y1 - y0
	gradient := 1.0
	if dx != 0 {
		gradient = dy / dx
	}

	fpart := func(x float64) float64 { return x - math.Floor(x) }
	rfpart := func(x float64) float64 { return 1.0 - fpart(x) }

	plot := func(x, y float64, brightness float64) {
		alpha := uint8(float64(col.A) * brightness)
		if alpha == 0 {
			return
		}
		c2 := color.RGBA{R: col.R, G: col.G, B: col.B, A: alpha}
		if steep {
			c.setPixel(int(y), int(x), c2)
		} else {
			c.setPixel(int(x), int(y), c2)
		}
	}

	xend := math.Round(x0)
	yend := y0 + gradient*(xend-x0)
	xgap := rfpart(x0 + 0.5)
	xpxl1 := xend
	ypxl1 := math.Floor(yend)
	plot(xpxl1, ypxl1, rfpart(yend)*xgap)
	plot(xpxl1, ypxl1+1, fpart(yend)*xgap)
	intery := yend + gradient

	xend = math.Round(x1)
	yend = y1 + gradient*(xend-x1)
	xgap = fpart(x1 + 0.5)
	xpxl2 := xend
	ypxl2 := math.Floor(yend)
	plot(xpxl2, ypxl2, rfpart(yend)*xgap)
	plot(xpxl2, ypxl2+1, fpart(yend)*xgap)

	for x := xpxl1 + 1; x < xpxl2; x++ {
		plot(x, math.Floor(intery), rfpart(intery))
		plot(x, math.Floor(intery)+1, fpart(intery))
		intery += gradient
	}
}

// Chart layout - matches go-chart's default layout
const (
	paddingLeft   = 12
	paddingRight  = 40  // for y-axis labels on right
	paddingTop    = 12
	paddingBottom = 25  // for x-axis labels at bottom
)

// renderGraph renders one graph into the canvas region [y0, y1)
func renderGraph(canvas *Canvas, w, graphY0, graphY1 int, gs GraphSpec, buf [][]float64, count, steps int) {
	if count == 0 {
		return
	}

	plotX0 := paddingLeft
	plotX1 := w - paddingRight
	plotY0 := graphY0 + paddingTop
	plotY1 := graphY1 - paddingBottom

	if plotX1 <= plotX0 || plotY1 <= plotY0 {
		return
	}
	plotW := plotX1 - plotX0
	plotH := plotY1 - plotY0

	// Find range across non-marker series
	minVal, maxVal := findRange(gs, buf, count, steps)

	// Draw axis
	drawAxisLines(canvas, plotX0, plotX1, plotY0, plotY1)

	// Draw each series
	numPoints := count
	if numPoints > steps {
		numPoints = steps
	}

	for si, fs := range gs {
		if si >= len(buf) {
			break
		}
		col := seriesColors[si%len(seriesColors)]
		if fs.Marker {
			drawMarker(canvas, buf[si], count, steps, numPoints, plotX0, plotX1, plotY0, plotY1, plotW)
		} else {
			drawSeries(canvas, buf[si], count, steps, numPoints, plotX0, plotX1, plotY0, plotY1, plotW, plotH, minVal, maxVal, col)
		}
	}

	// Draw axes (on top of series)
	drawYAxis(canvas, plotX1, plotY0, plotY1, w, minVal, maxVal)
	drawXAxis(canvas, plotX0, plotX1, plotY1, count, steps)
}

func findRange(gs GraphSpec, buf [][]float64, count, steps int) (float64, float64) {
	minVal := math.NaN()
	maxVal := math.NaN()

	numPoints := count
	if numPoints > steps {
		numPoints = steps
	}

	for si, fs := range gs {
		if fs.Marker || si >= len(buf) {
			continue
		}
		for i := 0; i < numPoints; i++ {
			pos := (count - numPoints + i) % steps
			v := buf[si][pos]
			if math.IsNaN(v) {
				continue
			}
			if math.IsNaN(minVal) || v < minVal {
				minVal = v
			}
			if math.IsNaN(maxVal) || v > maxVal {
				maxVal = v
			}
		}
	}

	if math.IsNaN(minVal) {
		return 0, 1
	}

	// Include 0 in range for positive data
	if minVal > 0 {
		minVal = 0
	}
	// Add 10% padding to max
	if maxVal > minVal {
		maxVal = maxVal + (maxVal-minVal)*0.1
	} else {
		maxVal = minVal + 1
	}

	return minVal, maxVal
}

func drawAxisLines(canvas *Canvas, x0, x1, y0, y1 int) {
	// Y-axis on right side
	for y := y0; y <= y1; y++ {
		canvas.setPixel(x1, y, axisColor)
	}
	// X-axis at bottom
	for x := x0; x <= x1; x++ {
		canvas.setPixel(x, y1, axisColor)
	}
}

// drawSeries renders a single data series as a filled area line chart.
// The chart always renders `steps` x-positions from left to right.
// The most recent data is at the RIGHT side. Empty positions use value=0.
func drawSeries(canvas *Canvas, data []float64, count, steps, numPoints, x0, x1, y0, y1, plotW, plotH int, minVal, maxVal float64, col color.RGBA) {
	fillCol := color.RGBA{R: col.R, G: col.G, B: col.B, A: 20}

	valueToY := func(v float64) float64 {
		yNorm := (v - minVal) / (maxVal - minVal)
		return float64(y1) - yNorm*float64(plotH)
	}

	prevX := -1.0
	prevY := -1.0

	var stepWidth float64
	if steps > 1 {
		stepWidth = float64(plotW) / float64(steps-1)
	} else {
		stepWidth = float64(plotW)
	}

	for i := 0; i < steps; i++ {
		xf := float64(x0) + float64(i)*stepWidth

		var v float64
		if i < steps-numPoints {
			// Empty step (before data started)
			v = 0
		} else {
			// Data step
			dataI := i - (steps - numPoints)
			pos := (count - numPoints + dataI) % steps
			dv := data[pos]
			if math.IsNaN(dv) {
				prevX = -1
				prevY = -1
				continue
			}
			v = dv
		}

		yf := valueToY(v)
		if yf < float64(y0) {
			yf = float64(y0)
		}

		// Fill below the line
		yFillStart := int(yf)
		if yFillStart < y0 {
			yFillStart = y0
		}
		for y := yFillStart; y <= y1; y++ {
			canvas.setPixel(int(xf), y, fillCol)
		}

		// Draw line segment
		if prevX >= 0 {
			canvas.drawLineAA(prevX, prevY, xf, yf, col)
		}

		prevX = xf
		prevY = yf
	}
}

func drawMarker(canvas *Canvas, data []float64, count, steps, numPoints, x0, x1, y0, y1, plotW int) {
	markerCol := color.RGBA{R: 0, G: 0, B: 0, A: 100}
	var stepWidth float64
	if steps > 1 {
		stepWidth = float64(plotW) / float64(steps-1)
	}
	for i := 0; i < steps; i++ {
		if i < steps-numPoints {
			continue
		}
		dataI := i - (steps - numPoints)
		pos := (count - numPoints + dataI) % steps
		v := data[pos]
		if math.IsNaN(v) || v == 0 {
			continue
		}
		xf := int(float64(x0) + float64(i)*stepWidth)
		for y := y0; y <= y1; y++ {
			canvas.setPixel(xf, y, markerCol)
		}
	}
}

func drawYAxis(canvas *Canvas, x1, y0, y1, canvasW int, minVal, maxVal float64) {
	numTicks := 8
	plotH := y1 - y0

	for i := 0; i <= numTicks; i++ {
		yf := y0 + plotH*i/numTicks
		val := maxVal - (maxVal-minVal)*float64(i)/float64(numTicks)

		// Tick mark
		for x := x1; x <= x1+4; x++ {
			canvas.setPixel(x, yf, axisColor)
		}

		// Label
		label := formatValue(val)
		textX := x1 + 6
		textY := yf - 5
		if textY < y0 {
			textY = y0
		}
		drawText(canvas, label, textX, textY, textColor)
	}
}

func drawXAxis(canvas *Canvas, x0, x1, y1, count, steps int) {
	numTicks := 8
	plotW := x1 - x0

	for i := 0; i <= numTicks; i++ {
		xf := x0 + plotW*i/numTicks
		// Tick mark
		for y := y1; y <= y1+4; y++ {
			canvas.setPixel(xf, y, axisColor)
		}
	}

	// Step count labels
	numLabels := 9
	for i := 0; i < numLabels; i++ {
		idx := i * steps / (numLabels - 1)
		if idx >= steps {
			idx = steps - 1
		}
		// The step idx corresponds to global step count - (steps-1-idx)
		stepNum := count - (steps - 1 - idx)
		if stepNum < 0 {
			stepNum = 0
		}
		label := fmt.Sprintf("%d", stepNum)

		xf := x0 + plotW*idx/(steps-1)
		textW := len(label) * 6
		textX := xf - textW/2
		drawText(canvas, label, textX, y1+6, textColor)
	}
}

func formatValue(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "N/A"
	}
	abs := math.Abs(v)
	if abs >= 1e9 {
		return fmt.Sprintf("%.2gG", v/1e9)
	} else if abs >= 1e6 {
		return fmt.Sprintf("%.2gM", v/1e6)
	} else if abs >= 1e3 {
		return fmt.Sprintf("%.2gk", v/1e3)
	} else if abs >= 100 {
		return fmt.Sprintf("%.0f", v)
	} else if abs >= 10 {
		return fmt.Sprintf("%.1f", v)
	} else if abs >= 1 {
		return fmt.Sprintf("%.2f", v)
	} else if abs > 0 {
		return fmt.Sprintf("%.3f", v)
	}
	return "0.00"
}
GOEOF

