	{R: 217, G: 0, B: 116, A: 255},   // #D90074 Pink
	{R: 0, G: 217, B: 210, A: 255},   // #00D9D2 Teal
	{R: 217, G: 101, B: 0, A: 255},   // #D96500 Orange
