		R: clamp8((srcA*float64(col.R) + dstA*(1-srcA)*float64(dst.R)) / outA),
		G: clamp8((srcA*float64(col.G) + dstA*(1-srcA)*float64(dst.G)) / outA),
		B: clamp8((srcA*float64(col.B) + dstA*(1-srcA)*float64(dst.B)) / outA),
		A: clamp8(outA * 255),
	})
