func findRange(gs GraphSpec, buf [][]float64, count, steps int) (float64, float64) {
	minVal := math.NaN()
	maxVal := math.NaN()

	numPoints := count
	if numPoints > steps {
		numPoints = steps
	}

	for si, fs := range gs {
		if fs.Marker || si >= len(buf) {
			continue
		}
		for i := 0; i < numPoints; i++ {
			pos := (count - numPoints + i) % steps
			v := buf[si][pos]
			if math.IsNaN(v) {
				continue
			}
			if math.IsNaN(minVal) || v < minVal {
				minVal = v
			}
			if math.IsNaN(maxVal) || v > maxVal {
				maxVal = v
			}
		}
	}

	if math.IsNaN(minVal) {
		return 0, 1
	}

	// Include 0 in range for positive data
	if minVal > 0 {
		minVal = 0
	}
	// Add 10% padding to max
	if maxVal > minVal {
		maxVal = maxVal + (maxVal-minVal)*0.1
	} else {
