func drawMarker(canvas *Canvas, data []float64, count, steps, numPoints, x0, x1, y0, y1, plotW int) {
	markerCol := color.RGBA{R: 0, G: 0, B: 0, A: 100}
	var stepWidth float64
	if steps > 1 {
		stepWidth = float64(plotW) / float64(steps-1)
	}
	for i := 0; i < steps; i++ {
		if i < steps-numPoints {
			continue
		}
		dataI := i - (steps - numPoints)
		pos := (count - numPoints + dataI) % steps
		v := data[pos]
		if math.IsNaN(v) || v == 0 {
			continue
		}
		xf := int(float64(x0) + float64(i)*stepWidth)
		for y := y0; y <= y1; y++ {
			canvas.setPixel(xf, y, markerCol)
		}
	}
}

func drawYAxis(canvas *Canvas, x1, y0, y1, canvasW int, minVal, maxVal float64) {
	numTicks := 8
	plotH := y1 - y0

	for i := 0; i <= numTicks; i++ {
		yf := y0 + plotH*i/numTicks
		val := maxVal - (maxVal-minVal)*float64(i)/float64(numTicks)

		// Tick mark
		for x := x1; x <= x1+4; x++ {
			canvas.setPixel(x, yf, axisColor)
		}

		// Label
		label := formatValue(val)
		textX := x1 + 6
		textY := yf - 5
		if textY < y0 {
			textY = y0
		}
		drawText(canvas, label, textX, textY, textColor)
	}
}

func drawXAxis(canvas *Canvas, x0, x1, y1, count, steps int) {
	numTicks := 8
	plotW := x1 - x0

	for i := 0; i <= numTicks; i++ {
		xf := x0 + plotW*i/numTicks
		// Tick mark
		for y := y1; y <= y1+4; y++ {
			canvas.setPixel(xf, y, axisColor)
		}
	}

	// Step count labels
	numLabels := 9
	for i := 0; i < numLabels; i++ {
		idx := i * steps / (numLabels - 1)
		if idx >= steps {
			idx = steps - 1
		}
		// The step idx corresponds to global step count - (steps-1-idx)
		stepNum := count - (steps - 1 - idx)
		if stepNum < 0 {
			stepNum = 0
		}
		label := fmt.Sprintf("%d", stepNum)

		xf := x0 + plotW*idx/(steps-1)
		textW := len(label) * 6
		textX := xf - textW/2
		drawText(canvas, label, textX, y1+6, textColor)
	}
}

func formatValue(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "N/A"
	}
	abs := math.Abs(v)
	if abs >= 1e9 {
		return fmt.Sprintf("%.2gG", v/1e9)
	} else if abs >= 1e6 {
		return fmt.Sprintf("%.2gM", v/1e6)
	} else if abs >= 1e3 {
		return fmt.Sprintf("%.2gk", v/1e3)
	} else if abs >= 100 {
		return fmt.Sprintf("%.0f", v)
	} else if abs >= 10 {
		return fmt.Sprintf("%.1f", v)
	} else if abs >= 1 {
		return fmt.Sprintf("%.2f", v)
	} else if abs > 0 {
		return fmt.Sprintf("%.3f", v)
	}
	return "0.00"
}
