new = """// Terminal detection
func detectTerminal() (Terminal, error) {
	openTTY()

	// Check TERM_PROGRAM for iTerm2 (direct match - no terminal query needed)
	termProg := os.Getenv("TERM_PROGRAM")
	if termProg == "iTerm.app" {
		return &ITerm2Terminal{}, nil
	}

	// Query terminal capabilities via ESC[c (Primary Device Attributes)
	// This is the primary detection method
	hasSixel, hasKitty := queryDAFull()
	if hasKitty {
		return &KittyTerminal{detected: true}, nil
	}
	if hasSixel {
		return &SixelTerminal{}, nil
	}

	// Check other environment variables for known terminals
	if os.Getenv("KITTY_WINDOW_ID") != "" {
		return &KittyTerminal{detected: true}, nil
	}

	switch termProg {
	case "WarpTerminal":
		return &ITerm2Terminal{}, nil
	}

	return nil, fmt.Errorf("iTerm2, Kitty, or DRCS Sixel graphics required")
}"""

